+    const infill = openingInfill(EAST, THICKNESS, { ...DOOR, swingAngle: 0 }, 0);
+    const size = extent(infill!.outline);
+    expect(size.width).toBeCloseTo(900, 6);
+    expect(size.depth).toBeCloseTo(40, 6);
+  });
