+  const positional = [];
+  let jsonOut = null;
+  let adapt = false;
+  for (let index = 0; index < argv.length; index += 1) {
+    if (argv[index] === '--json') {
+      jsonOut = argv[index + 1] ?? null;
+      index += 1;
+    } else if (argv[index] === '--adapt') {
+      adapt = true;
+    } else {
+      positional.push(argv[index]);
